SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(1000);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C48/inputs/portable_inputs.m";load "work/deg10/continuation_20261031b/C48/inputs/four_characters.m";load "work/deg10/continuation_20261031b/C48/inputs/two_isogeny_48_to_2_24.m";
root:="work/deg10/continuation_20261031b/C48/";k:=GF(5);R:=PolynomialRing(k);src:=eval Read(root cat "new_high_sources.m");fields:=AssociativeArray();for v in src[1]do fields[v[1]]:=ext<k|R!v[2]>;end for;CM:=Matrix(GF(2),[[x:x in row]:row in FilterCharacterRows]);KM:=Matrix(GF(2),[[x:x in row]:row in FilterCombinations]);M:=KM*CM;HM:=Matrix(GF(2),[[x:x in v[1..8]]:v in PortableRationalCusps]);assert Rank(M)eq 4 and IsZero(M*Transpose(HM));allowed:=AssociativeArray();allowed[0]:={[0,0,0,0]};allowed[1]:={Eltseq(Vector(GF(2),[x:x in PortableCuspClasses[i][1..8]])*Transpose(M)):i in[1..#PortableCuspDegrees]|PortableCuspDegrees[i]eq 1};needed:=[2,3,6,7,8];
function UV(b,c)if 1-c eq 0 then return false,[];end if;t:=2*b/(1-c)-1;if t eq 0 then return false,[];end if;q:=((1-c)*t^2-2)/(2*t);den:=t*(q^2+1)+2*q;if den*q eq 0 then return false,[];end if;ss:=t*(q^2-1)/den;dd:=(ss+2)/q;return true,[(ss+dd)/2,(ss-dd)/2];end function;
function SignAt(i,u,v)
 K:=Parent(u);val:=K!0;pow:=K!1;for pair in FilterFunctions[i]do den:=Evaluate(R!pair[2],v);if den eq 0 then return 0;end if;val+:=Evaluate(R!pair[1],v)/den*pow;pow*:=u;end for;if val eq 0 then return 0;end if;sg:=(val/K!FilterBaseValues[i])^((#K-1)div 2);assert sg in{K!1,-K!1};return sg eq 1 select 1 else -1;
end function;
function Key(v,d)ks:=[];for j in[1..d]do Append(~ks,&cat[[Integers()!a:a in Eltseq(z,k)]:z in v]);v:=[z^5:z in v];end for;return Sort(ks)[1];end function;
cases:=[* *];targets:=[* *];cache:=AssociativeArray();passing:=0;fallback:=0;
for si in[SHARD+1..#src[2]by NSHARDS]do id,d,ky:=Explode(src[2][si]);K:=fields[d];b:=Evaluate(R!ky[1..d],K.1);c:=Evaluate(R!ky[d+1..2*d],K.1);E:=EllipticCurve([K|1-c,-b,-b,0,0]);P:=E![0,0];EE,ls:=C48TwoIsogenousModuli(E,P);bc:=DerickxNormalForm_bc(EE,ls`P,ls`Q);e:=LCM([Degree(MinimalPolynomial(v,k)):v in bc]);assert d mod e eq 0 and d div e in[1,2];ok,uv:=UV(bc[1],bc[2]);sg:=[0:i in[1..8]];chi:=[];keep:=true;
 if ok then for i in needed do sg[i]:=SignAt(i,uv[1],uv[2]);end for;if &and[sg[i]ne 0:i in needed]then chi:=[(&*[sg[i]^combo[i]:i in needed|combo[i]ne 0])eq 1 select 0 else 1:combo in FilterCombinations];keep:=Vector(GF(2),chi)in{Vector(GF(2),v):v in allowed[10-d]};else fallback+:=1;end if;else fallback+:=1;end if;
 ix:=0;if keep then passing+:=1;ks:=[];for eps,eta in[0,1],u in[1,5,7,11]do v:=DerickxNormalForm_bc(EE,ls`P+eps*(12*ls`Q),u*ls`Q+eta*ls`P);Append(~ks,Key(v,d));end for;can:=Sort(ks)[1];ck:=[d,e,d div e]cat can;if IsDefined(cache,ck)then ix:=cache[ck];else Append(~targets,[*d,can,e,d div e*]);ix:=#targets;cache[ck]:=ix;end if;end if;
 Append(~cases,[*id,d,e,d div e,chi,keep,ix*]);if #cases mod 1000 eq 0 then print "D31B_C48_HIGH_CHARACTER_PROGRESS",SHARD,#cases,passing,#targets,fallback,Cputime(tt);end if;
end for;
Write(root cat TAG cat ".m",Sprint([*src[1],cases,targets*]):Overwrite:=true);print "D31B_C48_HIGH_CHARACTER_COMPLETE",SHARD,#cases,passing,#targets,fallback,Cputime(tt);quit;
